"""Exact weight-11/12 motivic arithmetic with comparison gates.

This module computes three pieces of data.

* The motivic Hoffman word count generated by 1/(1-x^2-x^3).
* The Newton identity for the repeated value zeta(3,3,3,3).
* Exact scalar arithmetic for powers of Delta_5/eta^12.

The repeated depth-four value is decomposable.  A cyclic cochain, a
Grothendieck--Teichmuller derivation, and a genus obstruction require
separate chain representatives and comparison maps.  The status
objects below record those obligations explicitly.
"""

from __future__ import annotations

from fractions import Fraction
from functools import lru_cache
from math import factorial
import re
from typing import Dict, List, Optional, Tuple, Union


Monomial = Tuple[int, ...]
Polynomial = Dict[Monomial, Fraction]


# --------------------------------------------------------------------
# Motivic Hoffman words and their dimensions
# --------------------------------------------------------------------

@lru_cache(maxsize=None)
def hoffman_words(weight: int) -> Tuple[Tuple[int, ...], ...]:
    """Return the compositions of weight with parts in {2, 3}.

    These index the motivic Hoffman basis.  Their count has generating
    series 1/(1-x^2-x^3).
    """
    if weight < 0:
        return ()
    if weight == 0:
        return ((),)

    words: List[Tuple[int, ...]] = []
    for first in (2, 3):
        for tail in hoffman_words(weight - first):
            words.append((first,) + tail)
    return tuple(words)


def padovan_dim(weight: int) -> int:
    """Motivic MZV dimension from d_w=d_{w-2}+d_{w-3}.

    The initial values are d_0=1, d_1=0, and d_2=1.
    Equivalently, this is the number of Hoffman {2,3} words.
    """
    return len(hoffman_words(weight))


def padovan_dim_11() -> int:
    """Return d_11=9."""
    return padovan_dim(11)


def padovan_dim_12() -> int:
    """Return d_12=12."""
    return padovan_dim(12)


def mzv_basis(weight: int) -> List[str]:
    """Return the motivic Hoffman basis at the requested weight."""
    return [
        (
            "1"
            if not word
            else "zeta(" + ",".join(str(part) for part in word) + ")"
        )
        for word in hoffman_words(weight)
    ]


def mzv_depth_of(entry: Union[str, Tuple[int, ...]]) -> int:
    """Return the maximum depth among zeta factors in entry."""
    if isinstance(entry, tuple):
        return len(entry)

    factors = re.findall(r"zeta\(([^)]*)\)", entry)
    if not factors:
        return 0
    return max(len([x for x in factor.split(",") if x.strip()])
               for factor in factors)


# --------------------------------------------------------------------
# Newton identities for repeated multiple zeta values
# --------------------------------------------------------------------

def _add_term(poly: Polynomial, monomial: Monomial,
              coefficient: Fraction) -> None:
    key = tuple(sorted(monomial))
    poly[key] = poly.get(key, Fraction(0)) + coefficient
    if poly[key] == 0:
        del poly[key]


def repeated_mzv_newton(single_weight: int, depth: int) -> Polynomial:
    r"""Return the exact Newton expansion of zeta({s}^depth).

    If p_k=zeta(k*s) and e_r=zeta(s,...,s) with r copies,
    Newton's identity reads

    r e_r = sum_{k=1}^r (-1)^(k-1) e_{r-k} p_k.

    A monomial (3,3,6) represents zeta(3)^2*zeta(6).
    """
    if single_weight <= 1:
        raise ValueError("single_weight must exceed 1")
    if depth < 0:
        raise ValueError("depth must be nonnegative")

    elementary: List[Polynomial] = [{(): Fraction(1)}]
    for r in range(1, depth + 1):
        numerator: Polynomial = {}
        for k in range(1, r + 1):
            sign = Fraction(1 if k % 2 else -1)
            power_sum_weight = single_weight * k
            for monomial, coefficient in elementary[r - k].items():
                _add_term(
                    numerator,
                    monomial + (power_sum_weight,),
                    sign * coefficient,
                )
        elementary.append({
            monomial: coefficient / r
            for monomial, coefficient in numerator.items()
        })
    return elementary[depth]


def zeta3333_newton_identity() -> Polynomial:
    r"""Return the exact decomposition of zeta(3,3,3,3).

    The output is

    1/24*zeta(3)^4 - 1/4*zeta(3)^2*zeta(6)
      + 1/8*zeta(6)^2 + 1/3*zeta(3)*zeta(9)
      - 1/4*zeta(12).
    """
    return repeated_mzv_newton(3, 4)


def zeta3333_status() -> dict:
    """Return the exact algebraic and comparison status."""
    return {
        "weight": 12,
        "depth": 4,
        "newton_identity": zeta3333_newton_identity(),
        "decomposable": True,
        "primitive_projection": 0,
        "first_depth_four_primitive": False,
        "graph_complex_class_constructed": False,
        "word_to_cyclic_cochain_map_constructed": False,
        "cyclic_cochain_constructed": False,
        "grt_action_computed": False,
        "status": (
            "exact MZV identity; graph-complex and cyclic-cochain "
            "comparisons open"
        ),
    }


def first_depth_4_entry_at_weight_12() -> None:
    """Compatibility alias: primitive status is represented by None."""
    return None


def mzv_has_depth_4_irreducible(weight: int) -> Optional[bool]:
    """Return the status of a depth-four primitive at weight.

    Membership of zeta(3,3,3,3) in a depth-four word list records
    depth, while its primitive projection is zero.  The existence of
    another depth-four class is a graph-complex calculation, so
    weight 12 returns None.
    """
    if weight == 12:
        return None
    return None


# --------------------------------------------------------------------
# Exact Borcherds scalar arithmetic
# --------------------------------------------------------------------

def sigma_1(n: int) -> int:
    """Return the sum of positive divisors of n."""
    if n <= 0:
        raise ValueError("n must be positive")
    return sum(d for d in range(1, n + 1) if n % d == 0)


def delta5_pure_q_log_coefficient(n: int) -> Fraction:
    r"""Coefficient of q^n y^0 p^0 in the unit-normalised log.

    The (d,0,0) factors of the Gritsenko--Nikulin product have
    exponent f(0,0)=10.  Therefore

    [q^n y^0 p^0] log(P_Delta5) = -10*sigma_1(n)/n.
    """
    if n <= 0:
        raise ValueError("n must be positive")
    return -Fraction(10 * sigma_1(n), n)


def borcherds_leg_weight_raw(n: int) -> int:
    """Weight of (Delta_5/eta^12)^n: 5n-6n=-n."""
    if n < 0:
        raise ValueError("n must be nonnegative")
    return -n


def borcherds_leg_is_half_integral(n: int) -> bool:
    """Return whether the resolved section carries nu_Delta5.

    Phi_10^(n/2)=Delta_5^n after choosing the distinguished square
    root.  Odd n carries the order-two Delta_5 character.
    """
    if n < 0:
        raise ValueError("n must be nonnegative")
    return bool(n % 2)


def borcherds_scalar_section(n: int) -> dict:
    """Describe the exact scalar section and its open cochain lift."""
    if n < 0:
        raise ValueError("n must be nonnegative")
    return {
        "order": n,
        "resolved_form": f"(Delta_5/eta^12)^{n}",
        "raw_weight": borcherds_leg_weight_raw(n),
        "delta5_character": "nu_Delta5" if n % 2 else "trivial",
        "product_exponent_scale": n,
        "ordinary_fourier_operation": f"{n}-fold convolution",
        "coefficient_to_cochain_map_constructed": False,
        "cyclic_closure_verified": False,
        "maurer_cartan_verified": False,
        "status": "exact scalar section; cyclic cochain lift open",
    }


def borcherds_leg_weight_total(n: int) -> None:
    """Compatibility alias for the retired in-tower weight."""
    if n < 0:
        raise ValueError("n must be nonnegative")
    return None


def borcherds_leg_weight_integrated(n: int) -> None:
    """Compatibility alias for the retired integrated weight."""
    if n < 0:
        raise ValueError("n must be nonnegative")
    return None


def borcherds_leg_asymptotic_dim(n: int) -> None:
    """Compatibility alias: the full Siegel coefficient needs a chamber."""
    if n <= 0:
        raise ValueError("n must be positive")
    return None


def borcherds_dominates_mzv(n: int) -> None:
    """Compatibility alias: scalar growth gives no cochain comparison."""
    if n < 0:
        raise ValueError("n must be nonnegative")
    return None


def borcherds_mzv_ratio(n: int) -> None:
    """Compatibility alias for the retired dimension ratio."""
    if n < 0:
        raise ValueError("n must be nonnegative")
    return None


# --------------------------------------------------------------------
# KZ and cyclic-cochain status
# --------------------------------------------------------------------

def kz_denominator(n: int) -> int:
    """Return the constant-integrand simplex denominator n!.

    A represented KZ word has its own regularised iterated integral.
    This function records only the simplex-volume normalisation.
    """
    if n < 0:
        raise ValueError("n must be nonnegative")
    return factorial(n)


def kz_normalization_status(n: int) -> dict:
    """Record the distinction between simplex volume and KZ words."""
    return {
        "weight": n,
        "constant_integrand_simplex_denominator": kz_denominator(n),
        "associator_chosen": False,
        "word_specified": False,
        "regularised_word_integral_computed": False,
        "word_to_cochain_map_constructed": False,
        "status": "simplex volume exact; represented KZ coefficient open",
    }


def phi_n_symbolic(n: int) -> dict:
    """Return an evidence inventory for the order-n candidate.

    The function records exact scalar inputs and the missing
    coefficient-to-cochain maps.  It therefore never promotes scalar
    arithmetic to a cyclic Maurer--Cartan operation.
    """
    if n < 0:
        raise ValueError("n must be nonnegative")

    return {
        "order": n,
        "hoffman_basis": mzv_basis(n),
        "motivic_dimension": padovan_dim(n),
        "kz_normalization": kz_normalization_status(n),
        "borcherds_scalar": borcherds_scalar_section(n),
        "zeta3333": zeta3333_status() if n == 12 else None,
        "kz_cochain_constructed": False,
        "borcherds_cochain_constructed": False,
        "rotation_equation_verified": False,
        "maurer_cartan_equation_verified": False,
        "phi_n_constructed": False,
        "status": "open cyclic comparison",
    }


# --------------------------------------------------------------------
# Weight truncations versus obstruction towers
# --------------------------------------------------------------------

def mittag_leffler_at_weight(weight: int) -> dict:
    """Separate the motivic quotient projection from a cyclic tower."""
    if weight < 0:
        raise ValueError("weight must be nonnegative")
    return {
        "weight": weight,
        "motivic_graded_dimension": padovan_dim(weight),
        "motivic_quotient_projection_surjective": True,
        "cyclic_obstruction_transition_constructed": False,
        "cyclic_obstruction_transition_surjective": None,
        "cyclic_lim1": None,
        "status": (
            "motivic quotient projection exact; cyclic obstruction "
            "inverse system open"
        ),
    }


def obs_infty_pro_limit_well_defined_through_weight_12() -> dict:
    """Return the exact motivic and open cyclic pro-limit statuses."""
    weights = {
        weight: mittag_leffler_at_weight(weight)
        for weight in range(3, 13)
    }
    return {
        "motivic_weight_projections": weights,
        "motivic_projections_surjective": True,
        "zeta3333_primitive_projection": 0,
        "cyclic_inverse_system_constructed": False,
        "lim1": None,
        "pro_limit_well_defined": None,
        "status": "cyclic pro-limit open pending transition maps",
    }


def obs_g_formula(g: int) -> dict:
    """Record the order range and comparison obligations at genus g."""
    if g < 0:
        raise ValueError("g must be nonnegative")
    top_order = g + 1
    return {
        "genus": g,
        "candidate_orders": tuple(range(1, top_order + 1)),
        "uses_phi_n_through_n_eq": top_order,
        "zeta3333_primitive_contribution": False,
        "gamma12_required": top_order >= 12,
        "phi12_cochain_constructed": False,
        "genus_comparison_map_constructed": False,
        "obs_g_constructed": False,
        "status": "open genus comparison",
    }


# --------------------------------------------------------------------
# Self-checks and summary
# --------------------------------------------------------------------

def run_tests() -> Dict[str, bool]:
    """Run exact internal consistency checks."""
    identity = zeta3333_newton_identity()
    expected: Polynomial = {
        (3, 3, 3, 3): Fraction(1, 24),
        (3, 3, 6): Fraction(-1, 4),
        (6, 6): Fraction(1, 8),
        (3, 9): Fraction(1, 3),
        (12,): Fraction(-1, 4),
    }

    phi12 = phi_n_symbolic(12)
    pro_limit = obs_infty_pro_limit_well_defined_through_weight_12()

    return {
        "hoffman_d11_is_9": padovan_dim_11() == 9,
        "hoffman_d12_is_12": padovan_dim_12() == 12,
        "dimension_recurrence_at_12": (
            padovan_dim(12) == padovan_dim(10) + padovan_dim(9)
        ),
        "newton_identity_exact": identity == expected,
        "zeta3333_decomposable": zeta3333_status()["decomposable"],
        "zeta3333_primitive_projection_zero": (
            zeta3333_status()["primitive_projection"] == 0
        ),
        "depth_four_primitive_unresolved": (
            mzv_has_depth_4_irreducible(12) is None
        ),
        "pure_q_height_1": (
            delta5_pure_q_log_coefficient(1) == Fraction(-10)
        ),
        "pure_q_height_2": (
            delta5_pure_q_log_coefficient(2) == Fraction(-15)
        ),
        "odd_section_character": (
            borcherds_scalar_section(11)["delta5_character"]
            == "nu_Delta5"
        ),
        "even_section_character": (
            borcherds_scalar_section(12)["delta5_character"]
            == "trivial"
        ),
        "phi12_is_open": not phi12["phi_n_constructed"],
        "phi12_grt_action_open": (
            not phi12["zeta3333"]["grt_action_computed"]
        ),
        "cyclic_pro_limit_open": (
            pro_limit["pro_limit_well_defined"] is None
        ),
        "genus11_requires_gamma12": obs_g_formula(11)["gamma12_required"],
    }


def summary() -> dict:
    """Return the exact arithmetic and open comparison ledger."""
    return {
        "weight_11_dimension": padovan_dim_11(),
        "weight_12_dimension": padovan_dim_12(),
        "zeta3333": zeta3333_status(),
        "phi_11": phi_n_symbolic(11),
        "phi_12": phi_n_symbolic(12),
        "pro_limit": obs_infty_pro_limit_well_defined_through_weight_12(),
        "genus_10": obs_g_formula(10),
        "genus_11": obs_g_formula(11),
    }


if __name__ == "__main__":
    import json

    def _coerce(value):
        if isinstance(value, dict):
            return {str(key): _coerce(item)
                    for key, item in value.items()}
        if isinstance(value, (list, tuple)):
            return [_coerce(item) for item in value]
        if isinstance(value, Fraction):
            return f"{value.numerator}/{value.denominator}"
        return value

    print(json.dumps(_coerce(summary()), indent=2, sort_keys=True))
    checks = run_tests()
    print(f"{sum(checks.values())}/{len(checks)} exact checks passed")
    if not all(checks.values()):
        raise SystemExit(1)
